+/*
+ * Subsystem field appears in a QHCI command/response/event: Peripheral
+ * (PERI) or Trust Management Engine Lite (TME-L).
+ */
+enum qhci_subsys {
+	QHCI_SUBSYS_PERI,
+	QHCI_SUBSYS_BT,
+	QHCI_SUBSYS_UWB,
+	QHCI_SUBSYS_TMEL,
+	QHCI_SUBSYS_MAX,
+};
