+static const char * const qhci_subsys_name[] = {
+	[QHCI_SUBSYS_PERI]	= "PERI",
+	[QHCI_SUBSYS_BT]	= "PERI BT",
+	[QHCI_SUBSYS_UWB]	= "UWB",
+	[QHCI_SUBSYS_TMEL]	= "TME-L",
+	[QHCI_SUBSYS_INVALID]	= "BT",
+};
