+		.get_settle_us = btusb_get_settle_us,
+		.post_setup    = btusb_post_setup_unified_bt,
+	},
+};
+
+static const struct qdfu_dlfw_cfg dfu_dlfw_cfgs_subsys[QBTC_SUBSYS_MAX][QBT_FW_MAX] = {
+	[QBTC_SUBSYS_PERI][QBT_FW_PATCH] = {
